import{z as s,x as p,o as t,c as B,q as l,j as r,D as e,d as A,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"刻蚀偏置与 OPC 回环","description":"","frontmatter":{"title":"刻蚀偏置与 OPC 回环","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etch-bias-opc-loop.md","filePath":"litho/etch-bias-opc-loop.md","lastUpdated":1791063341000}'),d={name:"litho/etch-bias-opc-loop.md"};function h(C,a,I,m,P,D){const o=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="刻蚀偏置与-opc-回环" tabindex="-1">刻蚀偏置与 OPC 回环 <a class="header-anchor" href="#刻蚀偏置与-opc-回环" aria-label="Permalink to &quot;刻蚀偏置与 OPC 回环&quot;">​</a></h1><div class="epigraph"><p>ADI 贴目标之后，腔体还要把边再挪一截；这截偏置该回写进 OPC 版本，而不是每个班次拿 AEI 去拧扫描机剂量。</p><footer>—— 对照 ADI/AEI 偏置、紧凑刻蚀核与 run-to-run 的分工；Levinson 对 after-etch 计量的区分</footer></div><p><a href="/litho/etch-loading-effect">上一课</a>把负载写成布局邻域。缺口是闭环：在线 AEI 看见偏置漂了，谁改、改哪一层模型。<a href="/litho/etch-in-opc">刻蚀进 OPC</a> 与 <a href="/litho/etch-model-calibration">刻蚀模型校准</a> 已写核如何进迭代、如何标定；本课钉<strong>量产回环</strong>：何时重拟合核、何时只调平均偏置、何时重工晶圆。CMP 形貌如何先毁掉焦深，留给<a href="/litho/cmp-topography">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>偏置 = AEI − ADI（同一部位）。它随腔体老化、聚合物积累、硬掩模厚度和开口率漂。<a href="/litho/adi-aei">ADI/AEI</a> 已要求两套控制图。回环错误形态：用 AEI 误差去改扫描机剂量——把刻蚀指纹写进光学，下层套刻和胶窗一起坏。正确分层：扫描机盯 ADI；刻蚀 APC 盯平均速率/偏置；密度形状的变化才触发 OPC 核重标定。</p><p><span class="marginnote">术语翻译：ADI/AEI 是「显影后检查」与「刻蚀后检查」——同一部位先量一次胶上的线宽，刻完再量一次，两者相减才是刻蚀偏置。只有 AEI 一套数据时，你手里只有总误差，分不清该怪扫描机还是怪腔体。</span></p><p>缺口是<strong>版本与频率</strong>，不是再拟合一次核。每片重 OPC 不可能；每季度重标定可能太慢。中间是偏置偏移量（global etch bias）进 APC，形状残差进工程触发器。</p><h3 id="回环不是实时-ilt" tabindex="-1">回环不是实时 ILT <a class="header-anchor" href="#回环不是实时-ilt" aria-label="Permalink to &quot;回环不是实时 ILT&quot;">​</a></h3><p>在线数据稀疏、有计量延迟、有抽样偏差（下一门过程控制会展开）。只能更新低维参数：全场平均、径向一次项，或许分密度档。二维 jog 的核形状仍靠工程实验片。把稀疏 AEI 直接当全芯片目标去反演 OPC，会拟合噪声。</p><p><span class="marginnote">OPC 版本号含刻蚀食谱 id 与核版本。腔体大保养后应走验证矩阵，而不是假定偏置连续可滑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：成对或对齐的 ADI/AEI、开口率图。决策树：平均偏置漂 → 刻蚀时间/过刻 APC；径向指纹 → 腔体匹配；密度斜率变 → 重采集校准片、更新核；局部新热点 → LRC/PWQ，可能改设计。与后课 APC、R2R 的关系：本课定义光刻–刻蚀分工；控制课写滤波与抽样。</p><p>仿真链：更新核后必须重跑关键层 LRC，不能只改表格里一个数。</p><p><span class="marginnote">数字实例：若 ADI 量得 \\(90\\,\\mathrm{nm}\\)、AEI 量得 \\(95\\,\\mathrm{nm}\\)，偏置就是 \\(+5\\,\\mathrm{nm}\\)（线条刻胖了）。下一版 OPC 把目标反向预缩 \\(5\\,\\mathrm{nm}\\)，让刻蚀把它「长回来」；期间均值的小漂移由 APC 调刻蚀时间吸收，不必发新核版本。</span></p>',14)),(t(),r(n,null,{default:e(()=>[i(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E5%B7%A5%E7%A8%8B%E7%89%87%E9%87%87%E9%9B%86%20ADI%20%E4%B8%8E%20AEI%22%5D%20--%3E%20FIT%5B%22%E6%8B%9F%E5%90%88%E5%88%BB%E8%9A%80%E6%A0%B8%22%5D%0A%20%20FIT%20--%3E%20VER%5B%22%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%20%E2%86%92%20%E5%8F%91%E5%B8%83%E6%A0%B8%E7%89%88%E6%9C%AC%22%5D%0A%20%20VER%20--%3E%20RUN%5B%22%E9%87%8F%E4%BA%A7%E8%BF%90%E8%A1%8C%EF%BC%9A%E5%81%8F%E7%BD%AE%E6%BB%91%E8%BF%9B%20APC%22%5D%0A%20%20RUN%20--%3E%20MON%7B%22%E5%AF%86%E5%BA%A6%E6%96%9C%E7%8E%87%E6%88%96%E7%83%AD%E7%82%B9%E8%A7%A6%E5%8F%91%E5%99%A8%E8%B6%8A%E9%99%90%22%7D%0A%20%20MON%20--%20%22%E6%9C%AA%E8%B6%8A%E9%99%90%22%20--%3E%20RUN%0A%20%20MON%20--%20%22%E8%B6%8A%E9%99%90%22%20--%3E%20REFIT%5B%22%E9%87%8D%E9%87%87%E9%9B%86%E6%A0%A1%E5%87%86%E7%89%87%20%E2%86%92%20%E6%96%B0%E6%A0%B8%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"触发器要数字化：密度斜率相对校准片偏多少、新热点是否只在一种开口率出现。含糊的「感觉偏了就重 OPC」会把核版本刷爆。SEMI 意义上的过程控制把低维更新和模型重辨识分开，本课沿用这道缝。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"平均偏置对应全球中性/离子水平；密度斜率对应微负荷与钝化。前者可周频更新，后者是模型结构。扫描机剂量主要动 ADI 均值，对刻蚀密度斜率几乎无能为力。故「AEI 偏了就加剂量」会在密孤立差上越补越歪。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：剂量不是万能旋钮。加剂量主要把 ADI 均值整体推粗，动不了刻蚀的密度斜率；密/孤立线一边补准了、另一边就超差，胶的工艺窗口还被压窄。这也是「回环要分层」的物理原因。")],-1)),(t(),r(n,null,{default:e(()=>[i(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20AEI%5B%22%E5%9C%A8%E7%BA%BF%20AEI%22%5D%20--%3E%20SPLIT%5B%22%E5%88%86%E5%B1%82%22%5D%0A%20%20SPLIT%20--%3E%20APC%5B%22%E5%B9%B3%E5%9D%87%E5%81%8F%E7%BD%AE%20%E2%86%92%20%E5%88%BB%E8%9A%80%20APC%22%5D%0A%20%20SPLIT%20--%3E%20CH%5B%22%E5%BE%84%E5%90%91%E6%8C%87%E7%BA%B9%20%E2%86%92%20%E8%85%94%E4%BD%93%22%5D%0A%20%20SPLIT%20--%3E%20OPC%5B%22%E5%AF%86%E5%BA%A6%E6%96%9C%E7%8E%87%20%E2%86%92%20%E6%A0%B8%E7%89%88%E6%9C%AC%22%5D%0A%20%20ADI%5B%22ADI%22%5D%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E5%89%82%E9%87%8F%20%2F%20%E7%84%A6%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 OPC 当每片控制环。不重写等离子体第一性原理。金属–via enclosure 的 AEI 目标属于此环的规格，不要改成 ADI 目标。</p><p>后课默认：偏置分层回写；扫描机不背刻蚀的锅。下一课形貌来自 CMP，它会先改焦点和对准，再改下一层的光学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>刻蚀偏置回环分层：均值进 APC，形状进核版本，禁止用 AEI 拧剂量。</li><li>OPC 版本绑定食谱；大保养后重验证。</li><li>稀疏计量只能更新低维参数。</li><li>出处：ADI/AEI 与计算光刻刻蚀核通称；Levinson 计量区分。</li></ul>',5))])}const u=s(d,[["render",h]]);export{f as __pageData,u as default};
